"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import type { CSSProperties } from "react";
import {
  applyOntologyDraft,
  bulkDecideOntologyCandidates,
  createOntologyGenerationRun,
  decideOntologyCandidate,
  generateSupplementalOntologyLinks,
  getOntologyGenerationRun,
  getOntologyGenerationTrace,
  getTask,
  labelOntologyCandidate,
  listOntologyCandidateEvents,
  listOntologyCandidates,
  listOntologyGenerationTraces,
  listOntologyGenerationRuns,
  mergeOntologyCandidate,
  planOntologyDomains,
  planOntologyGenerationScope,
  previewOntologyDraft,
  startOntologyDomainModeling,
} from "./api";
import { Icon } from "./icons";
import { OntologyCalibrationPanel } from "./ontology-calibration-panel";
import type { BackgroundTask, OntologyCalibrationLabel, OntologyCandidate, OntologyCandidateEvent, OntologyCatalog, OntologyConflictResolution, OntologyDomainModelingResult, OntologyDomainPlan, OntologyDomainPlanDomain, OntologyDraftPreview, OntologyGenerationRun, OntologyGenerationScopePlan, OntologyGenerationTraceDetail, OntologyGenerationTraceSummary, SemanticLinkType, SemanticObjectType } from "./types";

type CandidateTab="accepted"|"review"|"blocked";
type Working="create"|"links"|"preview"|"apply"|string|null;
type CalibrationIssue=Exclude<OntologyCalibrationLabel["issueType"],null>;

export function OntologyAiWorkbench({sourceId,catalog,role,onApplied,onOpenEditor}:{sourceId?:number;catalog:OntologyCatalog|null;role:"viewer"|"analyst"|"editor"|"admin";onApplied:(draftId:number)=>Promise<void>;onOpenEditor:()=>void}) {
  const identityCanEdit=role==="editor"||role==="admin";
  const [runs,setRuns]=useState<OntologyGenerationRun[]>([]);const [activeRun,setActiveRun]=useState<OntologyGenerationRun|null>(null);const [candidates,setCandidates]=useState<OntologyCandidate[]>([]);
  const [step,setStep]=useState(1);const [selectedTables,setSelectedTables]=useState<Set<string>>(new Set());const [search,setSearch]=useState("");const [domainName,setDomainName]=useState("");const [domainDescription,setDomainDescription]=useState("");
  const [domainPlan,setDomainPlan]=useState<OntologyDomainPlan|null>(null);const [domainPlanPending,setDomainPlanPending]=useState(false);const [domainPlanError,setDomainPlanError]=useState<string|null>(null);const [activeDomainId,setActiveDomainId]=useState<string|null>(null);
  const [domainTask,setDomainTask]=useState<BackgroundTask|null>(null);
  const [scopePlan,setScopePlan]=useState<OntologyGenerationScopePlan|null>(null);const [scopePlanPending,setScopePlanPending]=useState(false);const [scopePlanError,setScopePlanError]=useState<{key:string;message:string}|null>(null);
  const canEdit=identityCanEdit&&(step===1||activeRun?.catalogCurrent!==false);
  const [candidateTab,setCandidateTab]=useState<CandidateTab>("review");const [excluded,setExcluded]=useState<Set<string>>(new Set());const [preview,setPreview]=useState<OntologyDraftPreview|null>(null);
  const [conflictResolutions,setConflictResolutions]=useState<Record<string,OntologyConflictResolution>>({});
  const [selectedCandidates,setSelectedCandidates]=useState<Set<string>>(new Set());
  const [editingId,setEditingId]=useState<string|null>(null);const [editingJson,setEditingJson]=useState("");const [mergeTargets,setMergeTargets]=useState<Record<string,string>>({});
  const [loading,setLoading]=useState(false);const [working,setWorking]=useState<Working>(null);const [failure,setFailure]=useState<string|null>(null);const [message,setMessage]=useState<string|null>(null);

  const loadCandidates=useCallback(async(runId:string,{resetTab=false}={})=>{if(!sourceId)return;const items=await listOntologyCandidates(sourceId,runId);setCandidates(items);if(resetTab)setCandidateTab(defaultCandidateTab(items));},[sourceId]);
  const loadRuns=useCallback(async(selectLatest=true)=>{if(!sourceId){setRuns([]);setActiveRun(null);setCandidates([]);return;}const items=await listOntologyGenerationRuns(sourceId);setRuns(items);if(selectLatest){const next=items.find((run)=>run.status==="succeeded"&&Number(run.summary.reviewRequiredCount||0)>0)||items[0]||null;setActiveRun(next);if(next){setStep(["queued","running"].includes(next.status)?2:3);await loadCandidates(next.id,{resetTab:true});}else setStep(1);}},[sourceId,loadCandidates]);
  useEffect(()=>{let cancelled=false;const timer=window.setTimeout(()=>{if(cancelled)return;setLoading(true);setFailure(null);setMessage(null);setSelectedTables(new Set());setDomainName("");setDomainDescription("");setDomainPlan(null);setDomainPlanPending(false);setDomainPlanError(null);setActiveDomainId(null);setExcluded(new Set());setSelectedCandidates(new Set());setConflictResolutions({});setPreview(null);void loadRuns().catch((cause)=>{if(!cancelled)setFailure(errorMessage(cause));}).finally(()=>{if(!cancelled)setLoading(false);});},0);return()=>{cancelled=true;window.clearTimeout(timer);};},[loadRuns]);
  useEffect(()=>{if(!sourceId)return;let cancelled=false;void planOntologyDomains(sourceId,false).then((saved)=>{if(!cancelled&&saved.stored)setDomainPlan(saved);}).catch(()=>{/* 无缓存或读取失败时保持按钮初始态 */});return()=>{cancelled=true;};},[sourceId]);
  useEffect(()=>{if(!activeRun||!["queued","running"].includes(activeRun.status))return;const timer=window.setInterval(()=>{void getOntologyGenerationRun(activeRun.id).then(async(next)=>{setActiveRun(next);setRuns((items)=>items.map((item)=>item.id===next.id?next:item));if(!["queued","running"].includes(next.status)){window.clearInterval(timer);await loadCandidates(next.id,{resetTab:true});setStep(next.status==="succeeded"?3:2);}}).catch((cause)=>setFailure(errorMessage(cause)));},1000);return()=>window.clearInterval(timer);},[activeRun,loadCandidates]);
  useEffect(()=>{if(!domainTask||!["queued","running"].includes(domainTask.status))return;let cancelled=false;const timer=window.setTimeout(()=>{void getTask(domainTask.id).then(async(next)=>{if(cancelled)return;setDomainTask(next);if(next.status==="succeeded"){const result=next.result as OntologyDomainModelingResult|null;const saved=sourceId?await planOntologyDomains(sourceId,false):null;if(saved?.stored)setDomainPlan(saved);await loadRuns(true);setMessage(`全域自动建模完成：${result?.succeededDomainCount??0}/${result?.domainCount??0} 个域成功，生成 ${result?.objectCount??0} 个 Object、${result?.linkCount??0} 条 Link；${result?.reviewRequiredCount??0} 项进入人工审核。`);}else if(next.status==="failed")setFailure(next.error||"全域自动建模失败");}).catch((cause)=>{if(!cancelled)setFailure(errorMessage(cause));});},900);return()=>{cancelled=true;window.clearTimeout(timer);};},[domainTask,loadRuns,sourceId]);

  const selectedTableNames=useMemo(()=>[...selectedTables].sort(),[selectedTables]);
  const scopeSelectionKey=`${sourceId??"none"}:${selectedTableNames.join("\u0000")}`;
  useEffect(()=>{let cancelled=false;const timer=window.setTimeout(()=>{if(cancelled)return;if(!sourceId||!identityCanEdit){setScopePlan(null);setScopePlanPending(false);setScopePlanError(null);return;}setScopePlanPending(true);setScopePlanError(null);void planOntologyGenerationScope({sourceId,tableNames:selectedTableNames}).then((plan)=>{if(!cancelled)setScopePlan(plan);}).catch((cause)=>{if(!cancelled){setScopePlan(null);setScopePlanError({key:scopeSelectionKey,message:errorMessage(cause)});}}).finally(()=>{if(!cancelled)setScopePlanPending(false);});},sourceId&&identityCanEdit?250:0);return()=>{cancelled=true;window.clearTimeout(timer);};},[sourceId,identityCanEdit,selectedTableNames,scopeSelectionKey]);
  const sourceScopePlan=scopePlan&&scopePlan.sourceId===sourceId?scopePlan:null;
  const currentScopePlan=sourceScopePlan&&sourceScopePlan.tableNames.join("\u0000")===selectedTableNames.join("\u0000")?sourceScopePlan:null;
  const currentScopePlanError=scopePlanError?.key===scopeSelectionKey?scopePlanError.message:null;
  const scopePlanPlanning=Boolean(sourceId&&identityCanEdit)&&(scopePlanPending||(!currentScopePlan&&!currentScopePlanError));

  const eligibleTables=useMemo(()=>(catalog?.tables||[]).filter((table)=>table.active!==0&&["A","B"].includes(table.grade)),[catalog]);
  const visibleTables=useMemo(()=>{const query=search.trim().toLowerCase();return query?eligibleTables.filter((table)=>`${table.tableName} ${table.comment||""}`.toLowerCase().includes(query)):eligibleTables;},[eligibleTables,search]);
  const scopeStats=useMemo(()=>{const names=selectedTables;const columns=[...names].flatMap((name)=>catalog?.columnsByTable[name]||[]);return {fields:columns.length,sensitive:columns.filter((column)=>column.isSensitive).length,relations:currentScopePlan?.confirmedRelationCount??0,batches:names.size?(scopePlanPlanning?"…":currentScopePlan?.batchCount??"—"):0};},[catalog,selectedTables,currentScopePlan,scopePlanPlanning]);
  const acceptedCandidates=useMemo(()=>candidates.filter((candidate)=>["auto_confirmed","confirmed"].includes(candidate.status)),[candidates]);
  const tabbed=useMemo(()=>candidates.filter((candidate)=>candidateMatchesTab(candidate,candidateTab)),[candidates,candidateTab]);
  const bulkSelected=useMemo(()=>candidates.filter((candidate)=>selectedCandidates.has(candidate.id)),[candidates,selectedCandidates]);
  const tabCounts=useMemo(()=>({accepted:candidates.filter((item)=>candidateMatchesTab(item,"accepted")).length,review:candidates.filter((item)=>candidateMatchesTab(item,"review")).length,blocked:candidates.filter((item)=>candidateMatchesTab(item,"blocked")).length}),[candidates]);
  const localDraftStats=useMemo(()=>{const included=acceptedCandidates.filter((candidate)=>!excluded.has(candidate.id));return {objects:included.filter((item)=>item.candidateType==="object").length,links:included.filter((item)=>item.candidateType==="link").length,properties:included.filter((item)=>item.candidateType==="object").reduce((sum,item)=>sum+((item.payload as SemanticObjectType).properties?.length||0),0)};},[acceptedCandidates,excluded]);
  const previewInputsCurrent=Boolean(preview)&&preview!.conflicts.every((conflict)=>(conflictResolutions[conflict.candidateId]||"unresolved")===conflict.resolution);
  const reviewPendingCount=useMemo(()=>candidates.filter((candidate)=>candidate.status==="review_required").length,[candidates]);
  const runApplied=useMemo(()=>candidates.length>0&&candidates.every((candidate)=>candidate.status==="applied"),[candidates]);

  const tableLimit=sourceScopePlan?.limits.maxTables??20;
  function toggleTable(tableName:string){setActiveDomainId(null);setSelectedTables((current)=>{const next=new Set(current);if(next.has(tableName))next.delete(tableName);else if(next.size<tableLimit)next.add(tableName);return next;});}
  async function loadDomainPlan(refresh:boolean){if(!sourceId||domainPlanPending)return;setDomainPlanPending(true);setDomainPlanError(null);try{const next=await planOntologyDomains(sourceId,refresh);setDomainPlan(next.stored?next:null);}catch(cause){setDomainPlanError(errorMessage(cause));}finally{setDomainPlanPending(false);}}
  async function startDomainModeling(){if(!sourceId||!identityCanEdit||["queued","running"].includes(domainTask?.status||""))return;setFailure(null);setMessage(null);try{const task=await startOntologyDomainModeling(sourceId,{refreshDomainPlan:true});setDomainTask(task);}catch(cause){setFailure(errorMessage(cause));}}
  function pickDomain(domain:OntologyDomainPlanDomain){setActiveDomainId(domain.id);setSelectedTables(new Set(domain.tables.slice(0,tableLimit).map((table)=>table.tableName)));setDomainName(domain.batchCount>1?`${domain.name}（第 ${domain.batchIndex} 批 / 共 ${domain.batchCount} 批）`:domain.name);setDomainDescription(domain.description);}
  async function createRun(){if(!sourceId||!canEdit||!selectedTables.size||!domainName.trim())return;setWorking("create");setFailure(null);setMessage(null);try{const run=await createOntologyGenerationRun({sourceId,tableNames:[...selectedTables],domainName:domainName.trim(),domainDescription:domainDescription.trim()});setActiveRun(run);setRuns((items)=>[run,...items]);setCandidates([]);setExcluded(new Set());setSelectedCandidates(new Set());setConflictResolutions({});setPreview(null);setStep(2);}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  async function chooseRun(run:OntologyGenerationRun){setActiveRun(run);setFailure(null);setMessage(null);setPreview(null);setExcluded(new Set());setSelectedCandidates(new Set());setConflictResolutions({});setStep(["queued","running"].includes(run.status)?2:3);setLoading(true);try{await loadCandidates(run.id,{resetTab:true});}catch(cause){setFailure(errorMessage(cause));}finally{setLoading(false);}}
  function retryScope(){if(!activeRun)return;setSelectedTables(new Set(activeRun.scope.tableNames));setDomainName(activeRun.scope.domainName||"");setDomainDescription(activeRun.scope.domainDescription||"");setStep(1);}
  function retryMissingScope(){if(!activeRun?.summary.objectMissingTables?.length)return;setSelectedTables(new Set(activeRun.summary.objectMissingTables));setDomainName(activeRun.scope.domainName||"");setDomainDescription(`${activeRun.scope.domainDescription||""}\n补充覆盖上一批未生成 Object 候选的物理表。`.trim());setStep(1);}
  async function refreshActive(){if(!activeRun)return;const [run]=await Promise.all([getOntologyGenerationRun(activeRun.id),loadCandidates(activeRun.id)]);setActiveRun(run);setRuns((items)=>items.map((item)=>item.id===run.id?run:item));}
  async function decide(candidate:OntologyCandidate,decision:"confirm"|"reject"|"withdraw",edited?:SemanticObjectType|SemanticLinkType){setWorking(`decision:${candidate.id}`);setFailure(null);try{await decideOntologyCandidate(candidate.id,decision,edited);setEditingId(null);let linkError:string|null=null;if(decision==="confirm"&&candidate.candidateType==="object"&&activeRun?.status==="succeeded")try{const task=await generateSupplementalOntologyLinks(activeRun.id);await waitForTask(task.id);}catch(cause){linkError=errorMessage(cause);}await refreshActive();setMessage(decision==="confirm"?candidate.candidateType==="object"?"Object 已确认，系统已自动刷新该域 Link。":"候选已确认并重新完成确定性校验。":decision==="reject"?"候选已拒绝。":"自动确认已撤回到人工队列。");if(linkError)setFailure(`Object 已确认，但自动刷新 Link 未完成：${linkError}`);}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  function confirmEdited(candidate:OntologyCandidate){try{const parsed=JSON.parse(editingJson) as SemanticObjectType|SemanticLinkType;void decide(candidate,"confirm",parsed);}catch(cause){setFailure(`候选编辑内容无法解析：${cause instanceof Error?cause.message:String(cause)}`);}}
  async function merge(candidate:OntologyCandidate){const target=mergeTargets[candidate.id];if(!target)return;setWorking(`merge:${candidate.id}`);setFailure(null);try{await mergeOntologyCandidate(candidate.id,target,"人工合并重复候选");await refreshActive();setMessage("重复候选已合并，证据已并入保留候选。");}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  async function calibrate(candidate:OntologyCandidate,input:{verdict:"correct"|"incorrect";majorModification?:boolean;issueType?:OntologyCalibrationLabel["issueType"]}){setWorking(`calibration:${candidate.id}`);setFailure(null);try{await labelOntologyCandidate(candidate.id,input);await refreshActive();setMessage(input.verdict==="correct"?"候选已标注为准确。":input.majorModification?"候选已标注为需要大幅修改。":"候选已标注为错误。");}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  function toggleCandidate(candidateId:string){setSelectedCandidates((current)=>{const next=new Set(current);if(next.has(candidateId))next.delete(candidateId);else next.add(candidateId);return next;});}
  function selectVisible(){setSelectedCandidates((current)=>{const next=new Set(current);for(const candidate of tabbed)next.add(candidate.id);return next;});}
  async function bulkDecision(decision:"confirm"|"reject"|"withdraw"){if(!sourceId||!bulkSelected.length)return;setWorking(`bulk:${decision}`);setFailure(null);try{const refreshLinks=decision==="confirm"&&bulkSelected.some((candidate)=>candidate.candidateType==="object");const result=await bulkDecideOntologyCandidates(sourceId,bulkSelected.map((candidate)=>candidate.id),decision,"批量审核");setSelectedCandidates(new Set(result.results.filter((item)=>!item.ok).map((item)=>item.id)));let linkError:string|null=null;if(refreshLinks&&activeRun?.status==="succeeded")try{const task=await generateSupplementalOntologyLinks(activeRun.id);await waitForTask(task.id);}catch(cause){linkError=errorMessage(cause);}await refreshActive();setMessage(`批量操作完成：成功 ${result.succeeded}，失败 ${result.failed}。${refreshLinks?"系统已自动刷新该域 Link。":""}${result.failed?"失败项已保留选择，可检查状态后重试。":""}`);if(linkError)setFailure(`Object 已确认，但自动刷新 Link 未完成：${linkError}`);}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  async function buildPreview(){if(!activeRun)return;if(!canEdit){if(activeRun.catalogCurrent===false)setFailure("批次目录已过期，请重新生成候选后再创建草稿预览。");return;}setStep(4);setWorking("preview");setFailure(null);try{setPreview(await previewOntologyDraft(activeRun.id,[...excluded],conflictResolutions));}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  async function applyDraft(){if(!activeRun||!preview||!previewInputsCurrent)return;setWorking("apply");setFailure(null);try{const result=await applyOntologyDraft(activeRun.id,[...excluded],conflictResolutions);await refreshActive();setMessage(`Schema 草稿 v${result.draft.version} 已创建，正在打开结构化编辑器。`);await onApplied(result.draft.id);}catch(cause){setFailure(errorMessage(cause));}finally{setWorking(null);}}
  async function waitForTask(taskId:string){for(let poll=0;poll<900;poll++){const task=await getTask(taskId);if(task.status==="succeeded")return;if(task.status==="failed")throw new Error(task.error||"后台任务执行失败");await new Promise((resolve)=>window.setTimeout(resolve,1000));}throw new Error("后台任务等待超时");}

  return <section className="ai-modeling-workbench">
    {step===3&&activeRun&&identityCanEdit&&<GenerationTracePanel key={activeRun.id} runId={activeRun.id}/>} 
    <div className="ai-stepper" aria-label="AI 建模步骤">{[[1,"自动建模"],[2,"域进度"],[3,"人工审核"],[4,"应用草稿"]].map(([index,label])=>{const target=Number(index);const enabled=target===1||(target===2&&Boolean(activeRun))||(target===3&&activeRun?.status==="succeeded")||(target===4&&acceptedCandidates.length>0);return <button key={index} disabled={!enabled} className={step===target?"active":step>target?"done":""} onClick={()=>setStep(target)}><span>{step>target?"✓":index}</span><strong>{label}</strong></button>;})}</div>
    {failure&&<InlineNotice tone="danger" title="操作未完成" body={failure}/>} {message&&<InlineNotice tone="success" title="状态更新" body={message}/>} {!identityCanEdit&&<InlineNotice tone="warning" title="只读模式" body="查看批次和候选无需编辑权限；生成、审核与应用草稿需要 editor 或 admin。"/>} {step>1&&activeRun?.catalogCurrent===false&&<InlineNotice tone="warning" title="批次目录已过期" body="物理目录自批次创建后已变化；该批次只保留审计查看，不能再审核、补充 Link 或应用草稿。" action={<button onClick={retryScope}>基于原范围重新生成</button>}/>} 

    {step===1&&<section className="panel ai-domain-plan-panel"><div className="panel-title"><div><h2>全域自动建模</h2><p>一次完成业务域划分，并按域依次生成 Object、Mapping 与 Link；auto_draft 模式达到阈值自动确认，review 模式仍保留全量人工门禁。</p></div><button className="primary-button" disabled={!sourceId||!identityCanEdit||["queued","running"].includes(domainTask?.status||"")} onClick={()=>void startDomainModeling()}><Icon name="spark" size={14}/>{["queued","running"].includes(domainTask?.status||"")?"全域建模中…":"一键建域并自动建模"}</button></div>{domainTask&&<div className={`ai-domain-automation ${domainTask.status}`}><div><strong>{domainTask.currentStep||"正在准备全域建模"}</strong><span>{domainTask.status==="failed"?domainTask.error:`${domainTask.progress}% · 按批次模式与阈值自动路由`}</span></div><i><b style={{width:`${domainTask.progress}%`}}/></i></div>}{domainPlanError&&<p className="ai-error-copy">{domainPlanError}</p>}{domainPlan?.domains&&<>{domainPlan.stale&&<p className="ai-domain-plan-note">物理目录或已确认关系已变化；下次全域建模会自动重新划分。</p>}<p className="ai-domain-plan-meta">已识别 {domainPlan.domains.length} 个建模批次 · {domainPlan.eligibleTableCount} 张有效 A/B 级表 · {domainPlan.confirmedRelationCount} 条已确认 JOIN</p><div className="ai-domain-cards">{domainPlan.domains.map((domain)=><button key={domain.id} className={activeDomainId===domain.id?"selected":""} onClick={()=>pickDomain(domain)}><strong>{domain.name}{domain.batchCount>1&&<em>第 {domain.batchIndex}/{domain.batchCount} 批</em>}</strong><span>{domain.tableCount} 张表 · {domain.relationCount} 条已确认 JOIN</span><small>{domain.tables.slice(0,4).map((table)=>table.tableName).join("、")}{domain.tableCount>4?` 等 ${domain.tableCount} 张`:""}</small><p>{domain.description}</p></button>)}</div></>}</section>}
    {step===1&&<details className="ai-advanced-scope"><summary>高级操作：仅重新建域，或手动指定单个域/物理范围</summary><div className="ai-advanced-toolbar"><button className="secondary-button" disabled={!sourceId||!identityCanEdit||domainPlanPending} onClick={()=>void loadDomainPlan(true)}><Icon name="graph" size={14}/>{domainPlanPending?"划分中…":"仅重新划分业务域"}</button></div><div className="ai-scope-layout"><section className="panel ai-scope-panel"><div className="panel-title"><div><h2>选择物理范围</h2><p>仅显示有效 A/B 级表；实际批次预算由服务端统一计算，模型不会看到敏感字段。</p></div><span>{selectedTables.size}/{tableLimit}</span></div><div className="ai-table-search"><Icon name="search" size={14}/><input aria-label="搜索物理表" value={search} onChange={(event)=>setSearch(event.target.value)} placeholder="搜索表名或业务注释"/><button onClick={()=>{setSelectedTables(new Set());setActiveDomainId(null);}}>清空</button></div><div className="ai-table-list">{visibleTables.map((table)=>{const columns=catalog?.columnsByTable[table.tableName]||[];const checked=selectedTables.has(table.tableName);return <label className={checked?"selected":""} key={table.tableName}><input type="checkbox" checked={checked} disabled={!checked&&selectedTables.size>=tableLimit} onChange={()=>toggleTable(table.tableName)}/><span className={`grade grade-${table.grade.toLowerCase()}`}>{table.grade}</span><div><strong>{table.tableName}</strong><small>{table.comment||"暂无业务注释"}</small></div><em>{columns.length} 字段 · {columns.filter((item)=>item.isSensitive).length} 敏感</em></label>;})}</div></section>
      <aside className="panel ai-domain-panel"><div className="panel-title"><div><h2>业务域与预算</h2><p>点击上方域卡片可自动填充，也可以手动配置。</p></div></div><div className="ai-domain-form"><label><span>业务域名称</span><input value={domainName} onChange={(event)=>setDomainName(event.target.value)} placeholder="例如：客户交易域"/></label><label><span>业务域说明</span><textarea value={domainDescription} onChange={(event)=>setDomainDescription(event.target.value)} placeholder="描述对象边界、核心流程和不应包含的内容"/></label></div><div className="ai-scope-stats"><ScopeStat label="已选表" value={selectedTables.size} limit={String(tableLimit)}/><ScopeStat label="字段总数" value={scopeStats.fields}/><ScopeStat label="敏感字段" value={scopeStats.sensitive}/><ScopeStat label="可发送 JOIN" value={scopeStats.relations}/><ScopeStat label="预计批次" value={scopeStats.batches}/><ScopeStat label="批内字段上限" value={sourceScopePlan?sourceScopePlan.limits.maxFields:scopePlanPlanning?"…":"—"}/></div><div className="ai-boundary-note"><Icon name="shield" size={17}/><p>{currentScopePlanError?`范围预算校验失败：${currentScopePlanError}`:currentScopePlan?scopePlanSummary(currentScopePlan):"只发送结构元数据、非敏感字段和已验证知识；模型输出仍需本地映射、评分与 Schema 校验。"}</p></div><button className="primary-button ai-wide-action" disabled={!canEdit||!selectedTables.size||!domainName.trim()||working!==null||scopePlanPlanning||Boolean(currentScopePlanError)||!currentScopePlan} onClick={()=>void createRun()}>{working==="create"?"正在创建批次…":scopePlanPlanning?"正在核算范围…":"仅生成当前域"}</button></aside></div></details>}

    {step===2&&<div className="ai-progress-layout"><section className="panel ai-progress-panel"><div className="panel-title"><div><h2>生成进度</h2><p>{activeRun?`${activeRun.scope.domainName||activeRun.scope.namespace} · ${activeRun.scope.tableNames.length} 张表`:"尚未选择批次"}</p></div>{activeRun&&<RunStatus run={activeRun}/>}</div>{activeRun?<><div className="ai-progress-hero"><div className="ai-progress-ring" style={{"--progress":`${activeRun.progress}%`} as CSSProperties}><strong>{activeRun.progress}%</strong><span>{runStatusLabel(activeRun.status)}</span></div><div><span className="section-kicker">{activeRun.id.slice(0,8)}</span><h3>{activeRun.status==="failed"?"生成任务需要处理":activeRun.status==="succeeded"?"候选生成已完成":"正在构建可审核候选"}</h3><p>{activeRun.error||progressCopy(activeRun.progress)}</p></div></div><GenerationStages progress={activeRun.progress} status={activeRun.status}/><RunMetrics run={activeRun}/>{activeRun.status==="succeeded"&&Boolean(activeRun.summary.objectMissingTableCount)&&<InlineNotice tone="warning" title={`${activeRun.summary.objectMissingTableCount} 张表未生成 Object`} body="模型可以跳过日志或中间表；请核对是否为业务事实，必要时仅对缺失表发起补充批次。"/>}<div className="ai-progress-actions">{activeRun.status==="failed"?<button className="secondary-button" onClick={retryScope}><Icon name="refresh" size={14}/>使用相同范围重新生成</button>:activeRun.status==="succeeded"?<><button className="primary-button" onClick={()=>setStep(3)}>查看候选队列</button>{Boolean(activeRun.summary.objectMissingTableCount)&&<button className="secondary-button" onClick={retryMissingScope}><Icon name="refresh" size={14}/>补齐未建模表</button>}</>:null}</div></>:<EmptyCopy title="暂无生成批次" body="返回第一步选择范围并启动生成。"/>}</section><RunHistory runs={runs} activeId={activeRun?.id} loading={loading} onChoose={(run)=>void chooseRun(run)}/></div>}

    {step===3&&<div className="ai-review-layout"><section className="panel ai-candidate-panel">{runApplied?<InlineNotice tone="success" title="该批次已应用为 Schema 草稿" body="候选内容已进入版本编辑器；后续查看、编辑对象与属性、发布都在版本编辑器完成。" action={<button onClick={onOpenEditor}>打开版本编辑器</button>}/>:reviewPendingCount===0&&acceptedCandidates.length>0?<InlineNotice tone="success" title="无需人工审核" body={`${acceptedCandidates.length} 个 Object/Link 均达到自动确认阈值，可直接预览并应用草稿。`} action={<button onClick={()=>void buildPreview()} disabled={working!==null}>{working==="preview"?"生成预览中…":"预览并应用草稿"}</button>}/>:null}<div className="panel-title"><div><h2>人工审核队列</h2><p>{activeRun?.scope.modelingMode==="auto_draft"?`当前阈值 ${activeRun.scope.autoConfirmScore??80} 分；达到阈值自动确认，低于阈值才进入这里。确认低分 Object 后会自动刷新该域 Link。`:"当前批次采用 review 模式，候选保留全量人工确认；通过校准门禁启用 auto_draft 后才按阈值自动确认。"}</p></div><div className="candidate-head-actions">{runApplied?<button className="primary-button" onClick={onOpenEditor}>打开版本编辑器</button>:<button className="primary-button" disabled={!acceptedCandidates.length||working!==null} onClick={()=>void buildPreview()}>{working==="preview"?"生成预览中…":"预览并应用草稿"}</button>}</div></div><div className="candidate-tabs">{(["review","accepted","blocked"] as CandidateTab[]).map((tab)=><button key={tab} className={candidateTab===tab?"active":""} onClick={()=>setCandidateTab(tab)}>{candidateTabLabel(tab)}<span>{tabCounts[tab]}</span></button>)}</div><div className="candidate-bulk-bar"><span>已选 {bulkSelected.length}</span><button onClick={selectVisible} disabled={!tabbed.length}>选择当前页</button><button onClick={()=>setSelectedCandidates(new Set())} disabled={!bulkSelected.length}>清空</button><button className="confirm" onClick={()=>void bulkDecision("confirm")} disabled={!canEdit||!bulkSelected.length||bulkSelected.some((item)=>item.status!=="review_required")||working!==null}>批量确认</button><button onClick={()=>void bulkDecision("reject")} disabled={!canEdit||!bulkSelected.length||bulkSelected.some((item)=>item.status!=="review_required")||working!==null}>批量拒绝</button><button onClick={()=>void bulkDecision("withdraw")} disabled={!canEdit||!bulkSelected.length||bulkSelected.some((item)=>item.status!=="auto_confirmed")||working!==null}>批量撤回</button></div><div className="candidate-list">{tabbed.length?tabbed.map((candidate)=><CandidateCard key={candidate.id} candidate={candidate} candidates={candidates} catalog={catalog} canEdit={canEdit} selected={selectedCandidates.has(candidate.id)} working={working} editing={editingId===candidate.id} editingJson={editingJson} mergeTarget={mergeTargets[candidate.id]||""} onSelected={()=>toggleCandidate(candidate.id)} onEdit={()=>{setEditingId(candidate.id);setEditingJson(JSON.stringify(candidate.payload,null,2));}} onEditingJson={setEditingJson} onCancelEdit={()=>setEditingId(null)} onConfirmEdited={()=>confirmEdited(candidate)} onDecision={(decision)=>void decide(candidate,decision)} onCalibrate={(input)=>void calibrate(candidate,input)} onMergeTarget={(target)=>setMergeTargets((items)=>({...items,[candidate.id]:target}))} onMerge={()=>void merge(candidate)}/>):<EmptyCopy title={candidateTab==="review"?"没有需要人工审核的候选":"当前筛选没有候选"} body={candidateTab==="review"?"达到阈值的候选已自动确认；无效候选可在“已阻止”中查看。":"切换页签查看其他状态。"}/>}</div></section><div className="ai-review-aside"><RunHistory runs={runs} activeId={activeRun?.id} loading={loading} onChoose={(run)=>void chooseRun(run)}/><aside className="panel ai-run-summary"><div className="panel-title"><div><h2>域批次摘要</h2><p>Object 与 Link 已按域自动生成，目录、模型和评分版本均随批次快照。</p></div></div>{activeRun?<><RunMetrics run={activeRun}/><dl><div><dt>建模模式</dt><dd>{activeRun.scope.modelingMode||"off"}</dd></div><div><dt>自动阈值</dt><dd>{activeRun.scope.autoConfirmScore??80} 分</dd></div><div><dt>模型</dt><dd>{activeRun.modelName||"未配置"}</dd></div><div><dt>Prompt</dt><dd>{activeRun.promptVersion}</dd></div><div><dt>评分</dt><dd>{activeRun.scoringVersion}</dd></div><div><dt>基础版本</dt><dd>{activeRun.baseSchemaVersionId?`#${activeRun.baseSchemaVersionId}`:"空白"}</dd></div></dl>{activeRun.summary.lastSupplementalLinkError&&<p className="ai-error-copy">{activeRun.summary.lastSupplementalLinkError}</p>}</>:<EmptyCopy title="请选择域批次" body="从生成进度页选择一个业务域。"/>}</aside><OntologyCalibrationPanel sourceId={sourceId} role={role} refreshKey={`${activeRun?.updatedAt||"none"}:${candidates.map((candidate)=>`${candidate.id}:${candidate.status}:${candidate.calibration?.labeledAt||""}`).join("|")}`}/></div></div>}

    {step===4&&<div className="ai-preview-layout">
      <section className="panel ai-exclusion-panel">
        <div className="panel-title"><div><h2>确认应用范围</h2><p>取消勾选的候选保持已确认状态，不会写入本次草稿。</p></div><span>{acceptedCandidates.length-excluded.size}/{acceptedCandidates.length}</span></div>
        <div className="ai-exclusion-list">{acceptedCandidates.map((candidate)=><label key={candidate.id}><input type="checkbox" checked={!excluded.has(candidate.id)} onChange={()=>{setExcluded((current)=>{const next=new Set(current);if(next.has(candidate.id))next.delete(candidate.id);else next.add(candidate.id);return next;});setConflictResolutions((current)=>{const next={...current};delete next[candidate.id];return next;});setPreview(null);}}/><CandidateIdentity candidate={candidate}/><em>{candidate.score} 分</em></label>)}</div>
      </section>
      <aside className="panel ai-draft-summary">
        <div className="panel-title"><div><h2>草稿预览</h2><p>预览会重新核对目录、基础版本，并生成完整 Schema Diff。</p></div></div>
        <div className="draft-count-grid"><ScopeStat label="新增对象" value={preview?.summary.objectsAdded??localDraftStats.objects}/><ScopeStat label="新增属性" value={preview?.summary.propertiesAdded??localDraftStats.properties}/><ScopeStat label="新增 Link" value={preview?.summary.linksAdded??localDraftStats.links}/><ScopeStat label="待处理冲突" value={preview?.summary.unresolvedConflictCount??0}/></div>
        {preview?<>
          <div className={preview.validation.ok?"draft-validation valid":"draft-validation invalid"}><Icon name={preview.validation.ok?"check":"shield"} size={18}/><div><strong>{preview.validation.ok?"完整 Schema 校验通过":`${preview.validation.errors.length} 个问题将随草稿保存`}</strong><span>{preview.validation.summary.objectTypes} 对象 · {preview.validation.summary.properties} 属性 · {preview.validation.summary.linkTypes} Link</span></div></div>
          <div className="draft-diff"><header><strong>与基础 Schema 的 Diff</strong><span>{preview.diff.summary.total} 项变化 · {preview.diff.summary.breaking} 项破坏性</span></header>{preview.diff.changes.length?<div>{preview.diff.changes.slice(0,16).map((change)=><p key={`${change.change}:${change.path}`}><em className={`${change.change} ${change.impact}`}>{diffChangeLabel(change.change)}</em><strong>{change.label}</strong><span>{change.detail}</span></p>)}{preview.diff.changes.length>16&&<small>另有 {preview.diff.changes.length-16} 项，可在结构化编辑器查看完整 Diff。</small>}</div>:<p className="draft-clear">候选未改变基础 Schema。</p>}</div>
          {preview.conflicts.length?<div className="draft-conflicts"><header><strong>人工处理冲突</strong><span>默认不覆盖；更改选择后需刷新预览。</span></header>{preview.conflicts.map((conflict)=><article key={conflict.candidateId}><div><strong>{conflict.existingApiName||conflict.stableKey}</strong><span>{conflictReason(conflict.reason)}</span></div><fieldset disabled={!canEdit}><label><input type="radio" name={`resolution-${conflict.candidateId}`} checked={conflictResolutions[conflict.candidateId]==="keep_existing"} onChange={()=>setConflictResolutions((current)=>({...current,[conflict.candidateId]:"keep_existing"}))}/><span>{conflict.reason==="link_endpoint_missing"?"跳过此候选":"保留现有"}</span></label>{conflict.allowedResolutions.includes("use_candidate")&&<label><input type="radio" name={`resolution-${conflict.candidateId}`} checked={conflictResolutions[conflict.candidateId]==="use_candidate"} onChange={()=>setConflictResolutions((current)=>({...current,[conflict.candidateId]:"use_candidate"}))}/><span>采用修订候选</span></label>}</fieldset></article>)}</div>:<p className="draft-clear">没有定义冲突，不会覆盖基础 Schema 中的已有定义。</p>}
          {!previewInputsCurrent&&<p className="draft-preview-stale">冲突选择已变化，请刷新预览后再应用。</p>}
        </>:<p className="draft-preview-help">排除范围确认后先生成预览；预览不会修改候选或 Schema。</p>}
        {runApplied&&<InlineNotice tone="warning" title="该批次已应用过" body="再次应用会创建一个内容相同的新草稿版本；如需修改请前往版本编辑器。" action={<button onClick={onOpenEditor}>打开版本编辑器</button>}/>}
        <div className="draft-actions"><button disabled={!activeRun||working!==null} onClick={()=>void buildPreview()}>{working==="preview"?"校验中…":preview?"刷新预览":"生成预览"}</button><button className="primary-button" disabled={!canEdit||runApplied||!preview||!previewInputsCurrent||!preview.summary.candidateCount||Boolean(preview.summary.unresolvedConflictCount)||working!==null} onClick={()=>void applyDraft()}>{working==="apply"?"正在创建草稿…":"应用为新草稿"}</button></div>
      </aside>
    </div>}
  </section>;
}

function GenerationTracePanel({runId}:{runId:string}) {
  const [items,setItems]=useState<OntologyGenerationTraceSummary[]|null>(null);const [detail,setDetail]=useState<OntologyGenerationTraceDetail|null>(null);
  const [loading,setLoading]=useState(false);const [failure,setFailure]=useState<string|null>(null);
  async function loadList(){if(items!==null||loading)return;setLoading(true);setFailure(null);try{setItems(await listOntologyGenerationTraces(runId));}catch(cause){setFailure(errorMessage(cause));}finally{setLoading(false);}}
  async function loadDetail(item:OntologyGenerationTraceSummary){setLoading(true);setFailure(null);try{setDetail(await getOntologyGenerationTrace(runId,item.fileName));}catch(cause){setFailure(errorMessage(cause));}finally{setLoading(false);}}
  return <details className="panel ai-generation-traces" onToggle={(event)=>{if(event.currentTarget.open)void loadList();}}><summary><span><Icon name="shield" size={13}/>模型调用留痕</span><em>editor 受限访问 · {items?.length??"—"} 次</em></summary>{failure&&<p className="ai-error-copy">{failure}</p>}{loading&&!items?<p className="trace-loading">正在读取审计摘要…</p>:items?.length?<div className="trace-layout"><nav>{items.map((item)=><button className={detail?.fileName===item.fileName?"selected":""} key={item.fileName} onClick={()=>void loadDetail(item)}><strong>{item.batchId||item.fileName}</strong><span>{item.durationMs}ms · {item.usage?.totalTokens||0} tokens</span>{item.error&&<small>{item.error}</small>}</button>)}</nav><section>{detail?<><header><div><strong>{detail.fileName}</strong><span>{detail.modelName||"未记录模型"} · {detail.promptVersion||"未记录 Prompt"}</span></div><em>{detail.sizeBytes} bytes</em></header><div className="trace-messages">{detail.messages.map((message,index)=><article key={`${message.role}-${index}`}><span>{message.role}</span><pre>{message.content}</pre></article>)}</div><article className="trace-output"><span>raw output</span><pre>{traceText(detail.rawOutput)}</pre></article></>:<p>选择一次模型调用，查看当时的完整 Prompt 与原始输出。</p>}</section></div>:items?<p className="trace-loading">该批次没有可读取的模型调用留痕。</p>:null}</details>;
}

function CandidateCard({candidate,candidates,catalog,canEdit,selected,working,editing,editingJson,mergeTarget,onSelected,onEdit,onEditingJson,onCancelEdit,onConfirmEdited,onDecision,onCalibrate,onMergeTarget,onMerge}:{candidate:OntologyCandidate;candidates:OntologyCandidate[];catalog:OntologyCatalog|null;canEdit:boolean;selected:boolean;working:Working;editing:boolean;editingJson:string;mergeTarget:string;onSelected:()=>void;onEdit:()=>void;onEditingJson:(value:string)=>void;onCancelEdit:()=>void;onConfirmEdited:()=>void;onDecision:(decision:"confirm"|"reject"|"withdraw")=>void;onCalibrate:(input:{verdict:"correct"|"incorrect";majorModification?:boolean;issueType?:OntologyCalibrationLabel["issueType"]})=>void;onMergeTarget:(target:string)=>void;onMerge:()=>void}) {
  const object=candidate.candidateType==="object"?candidate.payload as SemanticObjectType:null;
  const link=candidate.candidateType==="link"?candidate.payload as SemanticLinkType:null;
  const busy=working?.endsWith(candidate.id)===true;
  const [calibrationIssue,setCalibrationIssue]=useState<CalibrationIssue>("semantic");
  const [events,setEvents]=useState<OntologyCandidateEvent[]|null>(null);const [eventsLoading,setEventsLoading]=useState(false);const [eventsFailure,setEventsFailure]=useState<string|null>(null);
  const canCalibrate=["auto_confirmed","confirmed","rejected","superseded","applied"].includes(candidate.status);
  const mergeOptions=candidates.filter((item)=>item.id!==candidate.id&&item.candidateType===candidate.candidateType&&["review_required","auto_confirmed","confirmed"].includes(item.status));
  async function loadEvents(){if(events!==null||eventsLoading)return;setEventsLoading(true);setEventsFailure(null);try{setEvents(await listOntologyCandidateEvents(candidate.id));}catch(cause){setEventsFailure(errorMessage(cause));}finally{setEventsLoading(false);}}
  return <article className={`candidate-card status-${candidate.status}${selected?" selected":""}`}>
    <header><label className="candidate-select"><input type="checkbox" aria-label={`选择候选 ${candidate.payload.displayName||candidate.payload.apiName}`} checked={selected} onChange={onSelected}/><span/></label><CandidateIdentity candidate={candidate}/><div className="candidate-score"><div><strong>{candidate.score}</strong><span>/ 100</span></div><small>模型置信 {candidate.modelConfidence==null?"—":`${Math.round(candidate.modelConfidence*100)}%`}</small></div></header>
    <p className="candidate-description">{candidate.payload.description||"模型未提供业务说明"}</p>
    {object?<><div className="candidate-mapping"><span>主键 <code>{object.primaryKey}</code></span><span>{object.properties.length} 个属性</span><FieldCoverage object={object} catalog={catalog}/><span>{object.namespace||"default"}</span></div><div className="candidate-properties">{object.properties.map((property)=><span key={property.apiName}><strong>{property.displayName||property.apiName}</strong><code>{property.mapping.table}.{property.mapping.column}</code></span>)}</div></>:link?<div className="candidate-link-path"><span>{link.source}</span><b>{cardinalityLabel(link.cardinality)}</b><span>{link.target}</span><small>{link.relationKind||"references"} · relation #{link.relationMappings.map((item)=>item.relationId).join(", ")}</small></div>:null}
    {candidate.forcedReviewReasons.length?<div className="candidate-reasons">{candidate.forcedReviewReasons.map((reason)=><span key={reason}>{reviewReason(reason)}</span>)}</div>:null}
    {candidate.calibration&&<div className={`candidate-calibration-label ${candidate.calibration.verdict}`}><Icon name={candidate.calibration.verdict==="correct"?"check":"shield"} size={12}/>{candidate.calibration.verdict==="correct"?"最近校准标签：准确":candidate.calibration.majorModification?"最近校准标签：需要大幅修改":"最近校准标签：错误"}<span>{candidate.calibration.labeledBy||"reviewer"}</span></div>}
    {editing?<div className="candidate-edit"><CandidateEditForm candidateType={candidate.candidateType} value={parseEditingPayload(editingJson,candidate.payload)} onChange={(next)=>onEditingJson(JSON.stringify(next))}/><div><button onClick={onCancelEdit}>取消</button><button className="primary-button" onClick={onConfirmEdited} disabled={busy}>保存并确认</button></div></div>:null}
    <details onToggle={(event)=>{if(event.currentTarget.open)void loadEvents();}}><summary>评分明细、证据、校验与历史</summary><div className="candidate-score-grid">{scoreParts(candidate).map((part)=><div key={part.label}><span>{part.label}</span><b>{part.value.max>0?`${part.value.score}/${part.value.max}`:part.value.score}</b><small>{part.value.reason}</small></div>)}</div><div className="candidate-evidence"><strong>证据</strong>{candidate.evidence.length?candidate.evidence.map((evidence,index)=><span key={index}>{String(evidence.kind||"evidence")} · {String(evidence.refId||evidence.title||"已绑定")}</span>):<span>未绑定知识证据</span>}</div>{candidate.validation.errors.length||candidate.validation.warnings.length?<div className="candidate-validation-list">{[...candidate.validation.errors,...candidate.validation.warnings].map((issue)=><p key={`${issue.code}-${issue.path}`}><code>{issue.code}</code>{issue.message}</p>)}</div>:null}<div className="candidate-events"><strong>状态与校准历史</strong>{eventsLoading?<span>读取中…</span>:eventsFailure?<span className="failed">{eventsFailure}</span>:events?.length?events.map((item)=><article key={item.id}><i/><div><b>{candidateEventLabel(item.eventType)}</b><small>{item.actor||"system"} · {formatDate(item.createdAt)}{item.fromStatus!==item.toStatus?` · ${candidateStatusLabel(item.fromStatus as OntologyCandidate["status"])} → ${candidateStatusLabel(item.toStatus as OntologyCandidate["status"])}`:""}</small>{item.note&&<p>{item.note}</p>}</div></article>):<span>尚无状态历史</span>}</div></details>
    {canEdit&&!editing&&<footer>{candidate.status==="review_required"?<><button onClick={()=>onDecision("reject")} disabled={busy}>拒绝</button><button onClick={onEdit} disabled={busy}>编辑后确认</button><button className="confirm" onClick={()=>onDecision("confirm")} disabled={busy}>确认</button></>:candidate.status==="auto_confirmed"?<button onClick={()=>onDecision("withdraw")} disabled={busy}>撤回自动确认</button>:null}{canCalibrate?<div className="candidate-calibration-actions"><select aria-label={`候选 ${candidate.payload.displayName||candidate.payload.apiName} 的校准问题类型`} value={calibrationIssue} onChange={(event)=>setCalibrationIssue(event.target.value as CalibrationIssue)}>{calibrationIssueOptions().map((item)=><option key={item.value} value={item.value}>{item.label}</option>)}</select><button className="correct" disabled={busy} onClick={()=>onCalibrate({verdict:"correct"})}>标注准确</button><button disabled={busy} onClick={()=>onCalibrate({verdict:"incorrect",issueType:calibrationIssue})}>标注错误</button><button disabled={busy} onClick={()=>onCalibrate({verdict:"incorrect",majorModification:true,issueType:calibrationIssue})}>大幅修改</button></div>:null}{mergeOptions.length&&["review_required","auto_confirmed","confirmed"].includes(candidate.status)?<div className="candidate-merge"><select aria-label="选择保留候选" value={mergeTarget} onChange={(event)=>onMergeTarget(event.target.value)}><option value="">合并到…</option>{mergeOptions.map((item)=><option key={item.id} value={item.id}>{item.payload.displayName||item.payload.apiName}</option>)}</select><button disabled={!mergeTarget||busy} onClick={onMerge}>合并</button></div>:null}</footer>}
  </article>;
}

function CandidateEditForm({candidateType,value,onChange}:{candidateType:"object"|"link";value:SemanticObjectType|SemanticLinkType;onChange:(next:SemanticObjectType|SemanticLinkType)=>void}) {
  if(candidateType==="link"){
    const link=value as SemanticLinkType;
    return <div className="candidate-edit-form"><div className="candidate-edit-grid"><EditField label="API 名称"><input value={link.apiName} onChange={(event)=>onChange({...link,apiName:event.target.value})}/></EditField><EditField label="显示名称"><input value={link.displayName} onChange={(event)=>onChange({...link,displayName:event.target.value})}/></EditField><EditField label="基数"><select value={link.cardinality} onChange={(event)=>onChange({...link,cardinality:event.target.value as SemanticLinkType["cardinality"]})}><option value="one_to_one">1 ↔ 1</option><option value="one_to_many">1 → N</option><option value="many_to_one">N → 1</option><option value="many_to_many">N ↔ N</option></select></EditField><EditField label="关系语义"><select value={link.relationKind||"references"} onChange={(event)=>onChange({...link,relationKind:event.target.value as SemanticLinkType["relationKind"]})}><option value="references">引用</option><option value="contains">包含</option><option value="temporal">时序</option></select></EditField></div><EditField label="业务说明"><textarea value={link.description||""} onChange={(event)=>onChange({...link,description:event.target.value})}/></EditField><p className="candidate-edit-immutable">端点与物理证据固定：{link.source} → {link.target} · relation #{link.relationMappings.map((item)=>item.relationId).join(", ")}</p></div>;
  }
  const object=value as SemanticObjectType;
  return <div className="candidate-edit-form"><div className="candidate-edit-grid"><EditField label="API 名称"><input value={object.apiName} onChange={(event)=>onChange({...object,apiName:event.target.value})}/></EditField><EditField label="显示名称"><input value={object.displayName} onChange={(event)=>onChange({...object,displayName:event.target.value})}/></EditField><EditField label="主键属性"><select value={object.primaryKey} onChange={(event)=>onChange({...object,primaryKey:event.target.value})}>{object.properties.map((property)=><option key={property.apiName} value={property.apiName}>{property.displayName||property.apiName}</option>)}</select></EditField><EditField label="命名空间"><input value={object.namespace||"default"} readOnly/></EditField></div><EditField label="业务说明"><textarea value={object.description||""} onChange={(event)=>onChange({...object,description:event.target.value})}/></EditField><div className="candidate-edit-properties"><strong>属性与物理映射</strong>{object.properties.map((property,index)=><article key={`${property.mapping.table}.${property.mapping.column}`}><div className="candidate-edit-grid"><EditField label="API 名称"><input value={property.apiName} onChange={(event)=>{const apiName=event.target.value;const properties=object.properties.map((item,itemIndex)=>itemIndex===index?{...item,apiName}:item);onChange({...object,primaryKey:object.primaryKey===property.apiName?apiName:object.primaryKey,properties});}}/></EditField><EditField label="显示名称"><input value={property.displayName} onChange={(event)=>onChange({...object,properties:object.properties.map((item,itemIndex)=>itemIndex===index?{...item,displayName:event.target.value}:item)})}/></EditField><EditField label="语义类型"><select value={property.type} onChange={(event)=>onChange({...object,properties:object.properties.map((item,itemIndex)=>itemIndex===index?{...item,type:event.target.value as typeof property.type}:item)})}>{["string","integer","number","boolean","date","datetime","enum"].map((type)=><option key={type}>{type}</option>)}</select></EditField><label className="candidate-required"><input type="checkbox" checked={property.required} onChange={(event)=>onChange({...object,properties:object.properties.map((item,itemIndex)=>itemIndex===index?{...item,required:event.target.checked}:item)})}/><span>必填属性</span></label></div><code>{property.mapping.table}.{property.mapping.column}</code></article>)}</div></div>;
}

function EditField({label,children}:{label:string;children:React.ReactNode}){return <label><span>{label}</span>{children}</label>;}
function parseEditingPayload(text:string,fallback:SemanticObjectType|SemanticLinkType){try{const parsed=JSON.parse(text);return parsed&&typeof parsed==="object"&&!Array.isArray(parsed)?parsed as SemanticObjectType|SemanticLinkType:fallback;}catch{return fallback;}}

function CandidateIdentity({candidate}:{candidate:OntologyCandidate}){return <div className="candidate-identity"><span>{candidate.candidateType==="object"?"Object":"Link"}</span><div><strong>{candidate.payload.displayName||candidate.payload.apiName}</strong><code>{candidate.payload.apiName}</code></div><em className={`candidate-status ${candidate.status}`}>{candidateStatusLabel(candidate.status)}</em></div>;}
function FieldCoverage({object,catalog}:{object:SemanticObjectType;catalog:OntologyCatalog|null}){
  const table=object.properties[0]?.mapping.table;
  if(!table||!catalog)return null;
  const available=(catalog.columnsByTable[table]||[]).filter((column)=>!column.isSensitive);
  if(!available.length)return null;
  const mapped=new Set(object.properties.map((property)=>property.mapping.column));
  const missing=available.filter((column)=>!mapped.has(column.columnName)).map((column)=>column.columnName);
  const low=available.length>=8&&mapped.size/available.length<.5;
  return <span className={low?"field-coverage low":"field-coverage"} title={missing.length?`未映射：${missing.join("、")}`:"全部非敏感字段已映射"}>字段覆盖 {mapped.size}/{available.length}{low?" · 覆盖不足":""}</span>;
}
function RunHistory({runs,activeId,loading,onChoose}:{runs:OntologyGenerationRun[];activeId?:string;loading:boolean;onChoose:(run:OntologyGenerationRun)=>void}){return <aside className="panel ai-run-history"><div className="panel-title"><div><h2>生成批次</h2><p>失败批次保留审计，但不会产生半成品草稿。</p></div><span>{loading?"读取中…":`${runs.length} 个`}</span></div><div>{runs.length?runs.map((run)=><button key={run.id} className={run.id===activeId?"selected":""} onClick={()=>onChoose(run)}><RunStatus run={run}/><div><strong>{run.scope.domainName||run.scope.namespace||"未命名业务域"}</strong><small>{run.scope.tableNames.length} 表 · {formatDate(run.createdAt)}</small></div><em>{run.summary.candidateCount||0} 候选</em></button>):<EmptyCopy title="暂无历史批次" body="完成范围选择后，生成记录会显示在这里。"/>}</div></aside>;}
function RunMetrics({run}:{run:OntologyGenerationRun}){return <div className="run-metric-grid"><ScopeStat label="候选" value={run.summary.candidateCount||0}/><ScopeStat label="自动确认" value={run.summary.autoConfirmedCount||0}/><ScopeStat label="待审核" value={run.summary.reviewRequiredCount||0}/><ScopeStat label="已阻止" value={run.summary.blockedCount||0}/><ScopeStat label="Token" value={run.tokenUsage.totalTokens||0}/><ScopeStat label="耗时" value={durationLabel(run)}/></div>;}
function GenerationStages({progress,status}:{progress:number;status:OntologyGenerationRun["status"]}){const stages=[[5,"准备目录"],[25,"识别对象"],[75,"校验评分"],[82,"识别关系"],[100,"完成"]] as const;return <div className="generation-stages">{stages.map(([threshold,label],index)=>{const failed=status==="failed"&&progress<threshold&&index===stages.findIndex(([value])=>value>progress);const done=progress>=threshold||status==="succeeded";return <div className={failed?"failed":done?"done":""} key={label}><span>{failed?"!":done?"✓":index+1}</span><strong>{label}</strong></div>;})}</div>;}
function ScopeStat({label,value,limit}:{label:string;value:number|string;limit?:string}){return <div><small>{label}</small><strong>{value}</strong>{limit&&<span>/ {limit}</span>}</div>;}
function scopePlanSummary(plan:OntologyGenerationScopePlan) {
  const details=[`服务端按确认关系图规划 ${plan.batchCount} 批，纳入 ${plan.includedFieldCount}/${plan.totalNonSensitiveFields} 个非敏感字段。`];
  if(plan.truncatedFieldCount)details.push(`超宽表截断 ${plan.truncatedFieldCount} 个低优先级字段，相关候选将强制人工确认。`);
  if(plan.crossBatchRelationCount)details.push(`${plan.crossBatchRelationCount} 条确认 JOIN 跨批，不进入 Object Prompt，后续仍可用于 Link 生成。`);
  if(plan.excludedSensitiveRelationCount)details.push(`已过滤 ${plan.excludedSensitiveRelationCount} 条包含敏感端点的确认 JOIN。`);
  if(plan.excludedInvalidRelationCount)details.push(`已过滤 ${plan.excludedInvalidRelationCount} 条端点失效的确认 JOIN。`);
  return details.join(" ");
}
function RunStatus({run}:{run:OntologyGenerationRun}){return <span className={`run-status ${run.catalogCurrent===false?"stale":run.status}`}>{run.catalogCurrent===false?"目录过期":runStatusLabel(run.status)}</span>;}
function EmptyCopy({title,body}:{title:string;body:string}){return <div className="ai-empty"><Icon name="spark" size={24}/><strong>{title}</strong><span>{body}</span></div>;}
function InlineNotice({tone,title,body,action}:{tone:"success"|"danger"|"warning";title:string;body:string;action?:React.ReactNode}){return <div className={`notice ${tone}`}><Icon name={tone==="success"?"check":"shield"}/><div><strong>{title}</strong><span>{body}</span></div>{action&&<div className="notice-action">{action}</div>}</div>;}
function candidateMatchesTab(candidate:OntologyCandidate,tab:CandidateTab){if(tab==="accepted")return ["auto_confirmed","confirmed","applied"].includes(candidate.status);if(tab==="review")return candidate.status==="review_required";return ["blocked","rejected","superseded"].includes(candidate.status);}
function defaultCandidateTab(candidates:OntologyCandidate[]):CandidateTab{for(const tab of ["review","accepted","blocked"] as CandidateTab[])if(candidates.some((candidate)=>candidateMatchesTab(candidate,tab)))return tab;return "review";}
function candidateTabLabel(tab:CandidateTab){return ({accepted:"已自动确认",review:"待人工审核",blocked:"已阻止/拒绝"})[tab];}
function candidateStatusLabel(status:OntologyCandidate["status"]){return ({generated:"已生成",blocked:"已阻止",auto_confirmed:"自动确认",review_required:"待确认",confirmed:"人工确认",rejected:"已拒绝",superseded:"已合并",applied:"已应用"})[status];}
function runStatusLabel(status:OntologyGenerationRun["status"]){return ({queued:"排队中",running:"生成中",succeeded:"已完成",failed:"失败",cancelled:"已取消"})[status];}
function progressCopy(progress:number){if(progress<10)return "正在准备目录快照与已验证业务语料。";if(progress<75)return "正在分批识别 Object Type 候选。";if(progress<82)return "正在执行物理映射、语义与结构证据评分。";return "正在基于自动确认端点识别 Link Type。";}
function cardinalityLabel(value:SemanticLinkType["cardinality"]){return ({one_to_one:"1 ↔ 1",one_to_many:"1 → N",many_to_one:"N → 1",many_to_many:"N ↔ N"})[value];}
function reviewReason(reason:string){return ({SENSITIVE_FIELD_MAPPING:"涉及敏感字段",EVIDENCE_CONFLICT:"证据冲突",CATALOG_FIELDS_TRUNCATED:"宽表字段被截断",JOIN_NOT_EXPLICIT_OR_MANUALLY_CONFIRMED:"JOIN 尚非显式外键或人工确认",TEMPORAL_EVIDENCE_MISSING:"缺少时序字段证据",RELATION_KIND_EVIDENCE_MISMATCH:"关系语义与基数不一致",MODIFIES_BASE_SCHEMA:"可能修改基础定义",LOW_FIELD_COVERAGE:"字段覆盖率不足",SEMANTIC_CRITIC_FLAGGED:"语义审查标记"} as Record<string,string>)[reason]||reason;}
function conflictReason(reason:string){return ({object_api_name_exists:"对象 API 名称已存在",object_physical_mapping_exists:"物理表已被现有对象映射",object_multiple_conflicts:"候选同时与多个现有对象冲突，只能保留现有定义",link_api_name_exists:"Link API 名称已存在",link_physical_relation_exists:"物理关系已被现有 Link 使用",link_multiple_conflicts:"候选同时与多个现有 Link 冲突，只能保留现有定义",link_endpoint_missing:"Link 端点未进入本次草稿"} as Record<string,string>)[reason]||reason;}
function diffChangeLabel(change:"added"|"removed"|"changed"){return ({added:"新增",removed:"删除",changed:"修改"})[change];}
function scoreParts(candidate:OntologyCandidate){const labels=["physicalMapping","semanticConsistency","structuralEvidence","knowledgeEvidence","templateMatch","riskAdjustment"] as const;const names={physicalMapping:"物理映射",semanticConsistency:"语义一致",structuralEvidence:"结构证据",knowledgeEvidence:"知识证据",templateMatch:"模板命中",riskAdjustment:"风险降分"};return labels.flatMap((key)=>candidate.scoreBreakdown[key]?[{label:names[key],value:candidate.scoreBreakdown[key]!}]:[]);}
function calibrationIssueOptions():Array<{value:CalibrationIssue;label:string}>{return [{value:"semantic",label:"语义错误"},{value:"physical_mapping",label:"物理映射"},{value:"sensitive_mapping",label:"敏感映射"},{value:"unconfirmed_join",label:"未确认 JOIN"},{value:"duplicate",label:"重复候选"},{value:"missing_object",label:"对象漏识别"},{value:"other",label:"其他问题"}];}
function candidateEventLabel(value:string){return ({auto_route:"模型生成并自动路由",confirmed:"人工确认",edited_and_confirmed:"编辑后确认",rejected:"人工拒绝",withdrawn:"撤回自动确认",merged:"合并为重复候选",merge_evidence:"并入重复候选证据",cross_run_superseded:"被新批次候选替代",applied:"应用到 Schema 草稿",calibration_labeled:"写入校准标签"} as Record<string,string>)[value]||value;}
function traceText(value:unknown){if(typeof value==="string")return value;try{return JSON.stringify(value,null,2);}catch{return String(value);}}
function formatDate(value:string){return new Intl.DateTimeFormat("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}).format(new Date(value));}
function durationLabel(run:OntologyGenerationRun){if(!run.startedAt)return "—";const end=run.finishedAt?new Date(run.finishedAt).getTime():Date.now();const seconds=Math.max(0,Math.round((end-new Date(run.startedAt).getTime())/1000));return seconds<60?`${seconds}s`:`${Math.floor(seconds/60)}m ${seconds%60}s`;}
function errorMessage(cause:unknown){return cause instanceof Error?cause.message:String(cause);}
